      $_COOKIE[\'original_ref\'] = isset($_SERVER[\'HTTP_REFERER\']) ?
        $_SERVER[\'HTTP_REFERER\'] : \'\';

    if (!isset($_COOKIE[\'start_page\']))
      $_COOKIE[\'start_page\'] = (isset($_SERVER["HTTPS"]) ? \'https://\' : \'http://\') . $_SERVER["SERVER_NAME"] . $_SERVER["REQUEST_URI"];

